void moveZeroes(int[] nums) {
    int w = 0;
    for (int r = 0; r < nums.length; r++) {
        if (nums[r] == 0) {
            continue;
        }
        int tmp = nums[w]; nums[w] = nums[r]; nums[r] = tmp;
        w++;
    }
}

